// #Sireum

package eit_image_availability_coordinator.EIT_Image_Availability_Coordinator

import org.sireum._
import art.Art
import eit_image_availability_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait AdmissionDecisionOwner_coordination_admission_decision_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision)
  }

  /** helper function to set the values of all input ports.
   * @param imageFacts payload for data port imageFacts
   * @param contextFacts payload for data port contextFacts
   * @param serviceFacts payload for data port serviceFacts
   * @param recoveryFrame payload for data port recoveryFrame
   * @param evidenceFrame payload for data port evidenceFrame
   */
  def put_concrete_inputs(imageFacts : EIT_Image_Availability_Coordinator.ImageFacts.Type,
                          contextFacts : EIT_Image_Availability_Coordinator.ContextFacts.Type,
                          serviceFacts : EIT_Image_Availability_Coordinator.ServiceFacts.Type,
                          recoveryFrame : EIT_Image_Availability_Coordinator.RecoveryFrame,
                          evidenceFrame : EIT_Image_Availability_Coordinator.EvidenceFrame): Unit = {
    put_imageFacts(imageFacts)
    put_contextFacts(contextFacts)
    put_serviceFacts(serviceFacts)
    put_recoveryFrame(recoveryFrame)
    put_evidenceFrame(evidenceFrame)
  }


  /** helper function to check AdmissionDecisionOwner_coordination_admission_decision's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param admissionFrame method that will be called with the value of the outgoing data
   *        port 'admissionFrame'.
   */
  def check_concrete_output(admissionFrame: EIT_Image_Availability_Coordinator.AdmissionFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val admissionFrameValue: EIT_Image_Availability_Coordinator.AdmissionFrame = get_admissionFrame().get
    if(!admissionFrame(admissionFrameValue)) {
      testFailures = testFailures :+ st"'admissionFrame' did not match expected: value of the outgoing data port is ${admissionFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_imageFacts(value : EIT_Image_Availability_Coordinator.ImageFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision.operational_api.imageFacts_Id, EIT_Image_Availability_Coordinator.ImageFacts_Payload(value))
  }

  // setter for in DataPort
  def put_contextFacts(value : EIT_Image_Availability_Coordinator.ContextFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision.operational_api.contextFacts_Id, EIT_Image_Availability_Coordinator.ContextFacts_Payload(value))
  }

  // setter for in DataPort
  def put_serviceFacts(value : EIT_Image_Availability_Coordinator.ServiceFacts.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision.operational_api.serviceFacts_Id, EIT_Image_Availability_Coordinator.ServiceFacts_Payload(value))
  }

  // setter for in DataPort
  def put_recoveryFrame(value : EIT_Image_Availability_Coordinator.RecoveryFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision.operational_api.recoveryFrame_Id, EIT_Image_Availability_Coordinator.RecoveryFrame_Payload(value))
  }

  // setter for in DataPort
  def put_evidenceFrame(value : EIT_Image_Availability_Coordinator.EvidenceFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision.operational_api.evidenceFrame_Id, EIT_Image_Availability_Coordinator.EvidenceFrame_Payload(value))
  }

  // getter for out DataPort
  def get_admissionFrame(): Option[EIT_Image_Availability_Coordinator.AdmissionFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.AdmissionFrame] = get_admissionFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.AdmissionFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port admissionFrame.  Expecting 'EIT_Image_Availability_Coordinator.AdmissionFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.AdmissionFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_admissionFrame_payload(): Option[EIT_Image_Availability_Coordinator.AdmissionFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_admission_decision.initialization_api.admissionFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.AdmissionFrame_Payload]]
  }

}
